      // The use of inline closures is to circumvent an issue where the compiler
      // allocates stack space for every case branch when no optimizations are
      // enabled. https://github.com/apple/swift-protobuf/issues/1034
      switch fieldNumber {
      case 1: try { try decoder.decodeSingularStringField(value: &self.templateID) }()
      case 2: try { try decoder.decodeSingularStringField(value: &self.preferenceID) }()
      default: break
      }
    }
  }

  public func traverse<V: SwiftProtobuf.Visitor>(visitor: inout V) throws {
    if !self.templateID.isEmpty {
      try visitor.visitSingularStringField(value: self.templateID, fieldNumber: 1)
    }
    if !self.preferenceID.isEmpty {
      try visitor.visitSingularStringField(value: self.preferenceID, fieldNumber: 2)
    }
    try unknownFields.traverse(visitor: &visitor)
  }

  public static func ==(lhs: S12RPTDefaultPreference, rhs: S12RPTDefaultPreference) -> Bool {
    if lhs.templateID != rhs.templateID {return false}
    if lhs.preferenceID != rhs.preferenceID {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
}
